input.command:
cd ~/Library/Application\ Support/Code/User && cp settings.json settings.json.bak && /opt/homebrew/bin/python3 - <<'EOF'
import json, collections
p = "settings.json"
d = json.load(open(p), object_pairs_hook=collections.OrderedDict)
d["terminal.integrated.profiles.osx"] = {
    "tmux": {
        "path": "/opt/homebrew/bin/tmux",
        "args": ["new-session"],
        "icon": "terminal-tmux"
    },
    "zsh": {"path": "/bin/zsh", "args": ["-l"]}
}
json.dump(d, open(p, "w"), indent=4)
open(p, "a").write("\n")
EOF
echo "--- verify ---" && /opt/homebrew/bin/python3 -c "import json;print(json.load(open('settings.json'))['terminal.integrated.profiles.osx'])"

